exercises.solutionCode:
#include <stddef.h>

/* 计数信号量：count 为当前可用资源数，max_count 为资源上限 */
typedef struct {
    int count;
    int max_count;
} Sem;

int sem_init(Sem *s, int initial, int max)
{
    if (s == NULL || max <= 0 || initial < 0 || initial > max) {
        return -1;
    }
    s->count = initial;
    s->max_count = max;
    return 0;
}

int sem_take(Sem *s)
{
    if (s == NULL || s->max_count <= 0 || s->count < 0 || s->count > s->max_count) {
        return -1;
    }
    if (s->count == 0) {
        return 0;
    }
    s->count--;
    return 1;
}

int sem_give(Sem *s)
{
    if (s == NULL || s->max_count <= 0 || s->count < 0 || s->count > s->max_count) {
        return -1;
    }
    if (s->count >= s->max_count) {
        return 0;
    }
    s->count++;
    return 1;
}
